package com.eventdrivencommerce.order;
import com.eventdrivencommerce.order.application.model.ProductSnapshot;import com.eventdrivencommerce.order.application.port.out.ProductCatalog;import io.restassured.RestAssured;import org.junit.jupiter.api.*;import org.springframework.boot.test.context.SpringBootTest;import org.springframework.boot.test.web.server.LocalServerPort;import org.springframework.test.context.DynamicPropertyRegistry;import org.springframework.test.context.DynamicPropertySource;import org.springframework.test.context.bean.override.mockito.MockitoBean;import org.testcontainers.containers.PostgreSQLContainer;import org.testcontainers.junit.jupiter.*;import java.math.BigDecimal;import java.util.UUID;import static io.restassured.RestAssured.given;import static org.hamcrest.Matchers.*;import static org.mockito.Mockito.when;
@Testcontainers @SpringBootTest(webEnvironment=SpringBootTest.WebEnvironment.RANDOM_PORT,properties={"order.outbox.publisher-enabled=false","spring.kafka.listener.auto-startup=false"}) class OrderApiIT {
 @Container static PostgreSQLContainer<?> postgres=new PostgreSQLContainer<>("postgres:17.9-alpine");@DynamicPropertySource static void props(DynamicPropertyRegistry r){r.add("spring.datasource.url",postgres::getJdbcUrl);r.add("spring.datasource.username",postgres::getUsername);r.add("spring.datasource.password",postgres::getPassword);}@LocalServerPort int port;@MockitoBean ProductCatalog products;
 @BeforeEach void setup(){RestAssured.port=port;}
 @Test void persistsOrderAndReplaysIdempotentRequest(){UUID product=UUID.randomUUID(),customer=UUID.randomUUID();when(products.get(product)).thenReturn(new ProductSnapshot(product,"SKU-1","Product",new BigDecimal("99.90"),"SEK",true));String body="{\"lines\":[{\"productId\":\"%s\",\"quantity\":2}],\"currency\":\"SEK\",\"shippingAddress\":{\"recipient\":\"Name\",\"line1\":\"Street\",\"postalCode\":\"123\",\"city\":\"City\",\"countryCode\":\"SE\"},\"billingAddress\":{\"recipient\":\"Name\",\"line1\":\"Street\",\"postalCode\":\"123\",\"city\":\"City\",\"countryCode\":\"SE\"}}".formatted(product);String id=given().header("X-Customer-ID",customer).header("Idempotency-Key","it-key").contentType("application/json").body(body).when().post("/api/v1/orders").then().statusCode(202).body("totalAmount",comparesEqualTo(199.8f)).extract().path("id");given().header("X-Customer-ID",customer).when().get("/api/v1/orders/"+id).then().statusCode(200).body("status",is("PENDING"));given().header("X-Customer-ID",customer).header("Idempotency-Key","it-key").contentType("application/json").body(body).when().post("/api/v1/orders").then().statusCode(200).body("id",is(id));}
}
